"use strict";
// .slvs serializer: builds SolveSpace 3.x text-format documents from a JSON model spec.
// Handles/entities are regenerated by the solver on load; we emit groups, params,
// requests and constraints only. Format derived from solvespace source (file.cpp,
// request.cpp, group.cpp, constrainteq.cpp).

const VERSION_HEADER = "﻿ SolveSpace REVa".replace("﻿ ", "﻿") ; // placeholder, fixed below

// Exact version string accepted by SolveSpace 3.1: 0xB1 0xB2 0xB3 "SolveSpaceREVa"
function versionHeader() {
  return Buffer.concat([
    Buffer.from([0xb1, 0xb2, 0xb3]),
    Buffer.from("SolveSpaceREVa\n\n\n", "ascii"),
  ]);
}

// Request type codes
const REQ = {
  WORKPLANE: 100,
  DATUM_POINT: 101,
  LINE_SEGMENT: 200,
  CUBIC: 300,
  CUBIC_PERIODIC: 301,
  CIRCLE: 400,
  ARC_OF_CIRCLE: 500,
};

// Group type codes (sketch.h Group::Type)
const GRP = {
  DRAWING_3D: 5000,
  DRAWING_WORKPLANE: 5001,
  EXTRUDE: 5100,
  LATHE: 5101,
  REVOLVE: 5102,
  HELIX: 5103,
  ROTATE: 5200,
  TRANSLATE: 5201,
};

// Constraint type codes
const CON = {
  POINTS_COINCIDENT: 20,
  PT_PT_DISTANCE: 30,
  HORIZONTAL: 80,
  VERTICAL: 81,
  DIAMETER: 90,
  PT_ON_CIRCLE: 100,
  ANGLE: 120,
  PARALLEL: 121,
  PERPENDICULAR: 122,
  EQUAL_LENGTH_LINES: 50,
  PT_ON_LINE: 42,
};

// Named workplane quaternions (w, vx, vy, vz) as used by SolveSpace references.
const PLANES = {
  XY: { q: [1, 0, 0, 0], ref: 1 },
  YZ: { q: [0.5, 0.5, 0.5, 0.5], ref: 2 },
  ZX: { q: [0.5, -0.5, -0.5, -0.5], ref: 3 },
};

function hex8(n) {
  return (n >>> 0).toString(16).padStart(8, "0");
}

// Group param handle: 0x800g000n  (g = group, n = index)
function groupParamHandle(g, n) {
  return (0x80000000 | (g << 16) | n) >>> 0;
}

function fmtF(x) {
  return Number(x).toFixed(20);
}

// ---- tiny arithmetic evaluator for named params: numbers, names, + - * / ( ) ----
function evalExpr(expr, vars) {
  if (typeof expr === "number") return expr;
  const s = String(expr).trim();
  if (s === "") throw new Error("empty numeric expression");
  let i = 0;
  function peek() { return s[i]; }
  function skipWs() { while (i < s.length && s[i] === " ") i++; }
  function parseExpr() {
    let v = parseTerm();
    for (;;) {
      skipWs();
      const c = peek();
      if (c === "+") { i++; v += parseTerm(); }
      else if (c === "-") { i++; v -= parseTerm(); }
      else return v;
    }
  }
  function parseTerm() {
    let v = parseUnary();
    for (;;) {
      skipWs();
      const c = peek();
      if (c === "*") { i++; v *= parseUnary(); }
      else if (c === "/") { i++; const d = parseUnary(); v /= d; }
      else return v;
    }
  }
  function parseUnary() {
    skipWs();
    if (peek() === "-") { i++; return -parseUnary(); }
    if (peek() === "+") { i++; return parseUnary(); }
    return parseAtom();
  }
  function parseAtom() {
    skipWs();
    const c = peek();
    if (c === "(") {
      i++;
      const v = parseExpr();
      skipWs();
      if (peek() !== ")") throw new Error(`expected ) at ${i} in "${s}"`);
      i++;
      return v;
    }
    if (c === undefined) throw new Error(`unexpected end in "${s}"`);
    if (/[0-9.]/.test(c)) {
      const m = /^[0-9]*\.?[0-9]+([eE][-+]?[0-9]+)?/.exec(s.slice(i));
      if (!m) throw new Error(`bad number at ${i} in "${s}"`);
      i += m[0].length;
      return parseFloat(m[0]);
    }
    if (/[a-zA-Z_]/.test(c)) {
      const m = /^[a-zA-Z_][a-zA-Z0-9_]*/.exec(s.slice(i));
      i += m[0].length;
      const name = m[0];
      if (!(name in vars)) throw new Error(`unknown param "${name}"`);
      return vars[name];
    }
    throw new Error(`unexpected '${c}' at ${i} in "${s}"`);
  }
  const v = parseExpr();
  skipWs();
  if (i !== s.length) throw new Error(`trailing junk in "${s}" at ${i}`);
  if (!Number.isFinite(v)) throw new Error(`non-finite value for "${s}"`);
  return v;
}

class Writer {
  constructor() {
    this.lines = [];
  }
  field(key, val) {
    this.lines.push(`${key}=${val}`);
  }
  add(what) {
    this.lines.push(what);
    this.lines.push("");
    this.lines.push("");
  }
  emit(h, def) {
    for (const [key, val] of def) {
      if (val === undefined || val === null) continue;
      if (typeof val === "number" && val === 0 && def.omitZero) continue;
      this.field(key, val);
    }
  }
  build() {
    return Buffer.concat([
      versionHeader(),
      Buffer.from(this.lines.join("\n") + "\n", "utf8"),
    ]);
  }
}

// Point reference: "entityId.pN" (N = point index) or "entityId.c" for circle center.
function resolvePointRef(sketchState, ref) {
  const m = /^([A-Za-z0-9_-]+)\.(p\d+|c)$/.exec(String(ref));
  if (!m) throw new Error(`bad point ref "${ref}" (use "id.p0", "id.p1", "id.c")`);
  const [, entId, pt] = m;
  const ent = sketchState.byId.get(entId);
  if (!ent) throw new Error(`unknown sketch entity id "${entId}" in ref "${ref}"`);
  let localIdx;
  if (pt === "c") {
    if (ent.type !== "circle") throw new Error(`"${ref}": .c only valid on circles`);
    localIdx = 0;
  } else {
    localIdx = parseInt(pt.slice(1), 10);
    if (localIdx < 0 || localIdx >= ent.pointCount) {
      throw new Error(`point index out of range in "${ref}"`);
    }
  }
  // non-datum points are entity(i+1); datum points are entity(0)
  const entityHandle = ent.reqHandle * 0x10000 + (ent.datum ? 0 : localIdx + 1);
  return entityHandle;
}

function resolveEntityRef(sketchState, ref) {
  const ent = sketchState.byId.get(String(ref));
  if (!ent) throw new Error(`unknown sketch entity id "${ref}"`);
  return ent.reqHandle * 0x10000 + 0; // main entity is entity(0)
}

function buildSlvs(model) {
  const w = new Writer();
  const vars = {};
  for (const [k, v] of Object.entries(model.params || {})) vars[k] = evalExpr(v, vars);

  const resolve = (x) => {
    const y = evalExpr(x, vars);
    if (!Number.isFinite(y)) {
      throw new Error(`non-finite numeric value for ${JSON.stringify(x)}`);
    }
    return y;
  };
  const resolveVec = (v) => v.map(resolve);
  // 3D vector with z defaulted to 0; used for operations where a missing
  // third component must not silently become NaN (NaN meshes export empty).
  const vec3 = (v, label) => {
    if (!Array.isArray(v) || v.length < 2 || v.length > 3) {
      throw new Error(`${label}: expected [x, y] or [x, y, z], got ${JSON.stringify(v)}`);
    }
    return [resolve(v[0]), resolve(v[1]), resolve(v.length > 2 ? v[2] : 0)];
  };

  // ---- groups & requests bookkeeping ----
  const groups = [];
  const requests = [];
  const params = [];
  const constraints = [];

  // group 1: #references (DRAWING_3D, order omitted)
  groups.push({
    h: 1, type: GRP.DRAWING_3D, order: 0, name: "#references",
    fields: [],
  });

  // reference workplane requests 1..3
  for (let r = 1; r <= 3; r++) {
    requests.push({ h: r, type: REQ.WORKPLANE, group: 1 });
    const plane = [PLANES.XY, PLANES.YZ, PLANES.ZX][r - 1];
    // origin x,y,z = params 16,17,18 (zeros, omitted); normal w,vx,vy,vz = 32..35
    const [qw, qx, qy, qz] = plane.q;
    params.push([r * 0x10000 + 32, qw]);
    if (qx !== 0) params.push([r * 0x10000 + 33, qx]);
    if (qy !== 0) params.push([r * 0x10000 + 34, qy]);
    if (qz !== 0) params.push([r * 0x10000 + 35, qz]);
  }

  let nextGroup = 2;
  let nextReq = 4;
  let nextCon = 1;

  // ---- sketches ----
  const sketchStates = new Map();
  for (const sk of model.sketches || []) {
    const g = nextGroup++;
    let planeSpec = sk.plane || "XY";
    let q, originEntity;
    if (typeof planeSpec === "string") {
      const p = PLANES[planeSpec.toUpperCase()];
      if (!p) throw new Error(`unknown named plane "${planeSpec}" (use XY/YZ/ZX)`);
      q = p.q;
      originEntity = p.ref * 0x10000 + 1; // origin point of reference workplane request
    } else if (planeSpec.q) {
      q = planeSpec.q;
      originEntity = PLANES.XY.ref * 0x10000 + 1;
    } else {
      throw new Error(`sketch "${sk.name}": plane must be "XY"|"YZ"|"ZX" or {q:[w,x,y,z]}`);
    }
    const activeWp = 0x80000000 + g * 0x10000; // group's workplane entity
    groups.push({
      h: g, type: GRP.DRAWING_WORKPLANE, order: g - 1, name: sk.name || `sketch-${g}`,
      fields: [
        ["Group.activeWorkplane.v", hex8(activeWp)],
        ["Group.subtype", 6000],
        ["Group.predef.q.w", fmtF(q[0])],
        q[1] !== 0 && ["Group.predef.q.vx", fmtF(q[1])],
        q[2] !== 0 && ["Group.predef.q.vy", fmtF(q[2])],
        q[3] !== 0 && ["Group.predef.q.vz", fmtF(q[3])],
        ["Group.predef.origin.v", hex8(originEntity)],
      ].filter(Boolean),
    });

    const state = {
      group: g,
      activeWp,
      byId: new Map(),
      entities: sk.entities || [],
      constraints: sk.constraints || [],
    };

    for (const ent of state.entities) {
      const r = nextReq++;
      const id = ent.id || `e${r}`;
      if (state.byId.has(id)) throw new Error(`duplicate entity id "${id}" in sketch "${sk.name}"`);
      const construction = ent.construction ? 1 : 0;
      switch (ent.type) {
        case "line": {
          const a = resolveVec(ent.a);
          const b = resolveVec(ent.b);
          requests.push({ h: r, type: REQ.LINE_SEGMENT, group: g, workplane: activeWp, construction });
          params.push([r * 0x10000 + 16, a[0]], [r * 0x10000 + 17, a[1]]);
          params.push([r * 0x10000 + 19, b[0]], [r * 0x10000 + 20, b[1]]);
          state.byId.set(id, { type: "line", reqHandle: r, pointCount: 2, datum: false });
          break;
        }
        case "circle": {
          const c = resolveVec(ent.center);
          const rad = resolve(ent.r ?? ent.radius);
          if (!(rad > 0)) throw new Error(`circle "${id}": radius must be > 0`);
          requests.push({ h: r, type: REQ.CIRCLE, group: g, workplane: activeWp, construction });
          params.push([r * 0x10000 + 16, c[0]], [r * 0x10000 + 17, c[1]]);
          params.push([r * 0x10000 + 0x40, rad]);
          state.byId.set(id, { type: "circle", reqHandle: r, pointCount: 1, datum: false });
          break;
        }
        case "arc": {
          const c = resolveVec(ent.center);
          const s = resolveVec(ent.start);
          const e = resolveVec(ent.end);
          requests.push({ h: r, type: REQ.ARC_OF_CIRCLE, group: g, workplane: activeWp, construction });
          params.push([r * 0x10000 + 16, c[0]], [r * 0x10000 + 17, c[1]]);
          params.push([r * 0x10000 + 19, s[0]], [r * 0x10000 + 20, s[1]]);
          params.push([r * 0x10000 + 22, e[0]], [r * 0x10000 + 23, e[1]]);
          state.byId.set(id, { type: "arc", reqHandle: r, pointCount: 3, datum: false });
          break;
        }
        case "point": {
          const p = resolveVec(ent.at);
          requests.push({ h: r, type: REQ.DATUM_POINT, group: g, workplane: activeWp, construction });
          params.push([r * 0x10000 + 16, p[0]], [r * 0x10000 + 17, p[1]]);
          state.byId.set(id, { type: "point", reqHandle: r, pointCount: 1, datum: true });
          break;
        }
        default:
          throw new Error(`unknown sketch entity type "${ent.type}" in "${id}"`);
      }
    }

    for (const con of state.constraints || []) {
      const c = nextCon++;
      const base = { h: c, group: g, workplane: activeWp };
      const t = con.type;
      const needValP = ["on_line", "same_orientation"].includes(t);
      switch (t) {
        case "coincident": {
          constraints.push({ ...base, type: CON.POINTS_COINCIDENT,
            ptA: resolvePointRef(state, con.a), ptB: resolvePointRef(state, con.b) });
          break;
        }
        case "distance": {
          constraints.push({ ...base, type: CON.PT_PT_DISTANCE,
            ptA: resolvePointRef(state, con.a), ptB: resolvePointRef(state, con.b), valA: resolve(con.value) });
          break;
        }
        case "horizontal": {
          constraints.push({ ...base, type: CON.HORIZONTAL, entityA: resolveEntityRef(state, con.line) });
          break;
        }
        case "vertical": {
          constraints.push({ ...base, type: CON.VERTICAL, entityA: resolveEntityRef(state, con.line) });
          break;
        }
        case "diameter": {
          constraints.push({ ...base, type: CON.DIAMETER, entityA: resolveEntityRef(state, con.circle), valA: resolve(con.value) });
          break;
        }
        case "angle": {
          constraints.push({ ...base, type: CON.ANGLE, entityA: resolveEntityRef(state, con.a), entityB: resolveEntityRef(state, con.b), valA: resolve(con.value) });
          break;
        }
        case "equal_length": {
          constraints.push({ ...base, type: CON.EQUAL_LENGTH_LINES, entityA: resolveEntityRef(state, con.a), entityB: resolveEntityRef(state, con.b) });
          break;
        }
        case "parallel": {
          constraints.push({ ...base, type: CON.PARALLEL, entityA: resolveEntityRef(state, con.a), entityB: resolveEntityRef(state, con.b) });
          break;
        }
        case "perpendicular": {
          constraints.push({ ...base, type: CON.PERPENDICULAR, entityA: resolveEntityRef(state, con.a), entityB: resolveEntityRef(state, con.b) });
          break;
        }
        case "on_circle": {
          constraints.push({ ...base, type: CON.PT_ON_CIRCLE, ptA: resolvePointRef(state, con.point), entityA: resolveEntityRef(state, con.circle) });
          break;
        }
        case "on_line": {
          constraints.push({ ...base, type: CON.PT_ON_LINE, ptA: resolvePointRef(state, con.point), entityA: resolveEntityRef(state, con.line), needValP: true });
          break;
        }
        default:
          throw new Error(`unknown constraint type "${t}"`);
      }
    }

    sketchStates.set(sk.name || `sketch-${g}`, state);
  }

  // ---- boolean / pattern operations ----
  const opGroupOf = new Map();
  // allow sketches to be referenced by name as op sources
  for (const [name, st] of sketchStates) opGroupOf.set(name, st.group);

  for (const op of model.operations || []) {
    const from = op.from;
    if (!opGroupOf.has(from)) throw new Error(`operation ${op.type}: unknown source "${from}"`);
    const srcGroup = opGroupOf.get(from);
    const fields = [
      ["Group.opA.v", hex8(srcGroup)],
    ];
    let extraParams = [];
    // SolveSpace's ONE_SIDED ops apply the stored vector * timesApplied, and
    // timesApplied doubles per step (a*2), so the stored magnitude is HALF the
    // user-facing height/step. We accept the real dimension and store half.

    // ROTATE/REVOLVE/HELIX equations pin params 0-2 and 4-6 to
    // predef.origin / predef.entityB geometry, so we must emit real
    // entities for the center point and the rotation axis. Use a dedicated
    // helper workplane group allocated BEFORE the op group. LATHE only
    // needs the predef entities (no equations), but shares the same frame.
    let rotateFrame = null;
    if (["rotate", "revolve", "lathe", "helix"].includes(op.type)) {
      const c = vec3(op.center ?? [0, 0, 0], `${op.type}.center`);
      const axisRaw = vec3(op.axis ?? [0, 0, 1], `${op.type}.axis`);
      const len = Math.hypot(axisRaw[0], axisRaw[1], axisRaw[2]);
      if (!(len > 0)) throw new Error(`${op.type}: axis must be non-zero`);
      const axis = axisRaw.map((x) => x / len);
      if (Math.abs(c[2]) > 1e-12) throw new Error(`${op.type}: center must lie in the XY plane (z = 0)`);
      const isZAxis = Math.abs(axis[2] - 1) < 1e-9 && Math.abs(axis[0]) < 1e-12 && Math.abs(axis[1]) < 1e-12;
      if (!isZAxis && Math.abs(axis[2]) > 1e-12) {
        throw new Error(`${op.type}: axis must be +Z or lie in the XY plane`);
      }
      const hg = nextGroup++;
      const hWp = 0x80000000 | (hg << 16);
      groups.push({ h: hg, type: GRP.DRAWING_WORKPLANE, order: hg - 1, name: `rotate-frame-${hg}`,
        fields: [
          ["Group.activeWorkplane.v", hex8(hWp)],
          ["Group.subtype", 6000],
          ["Group.predef.q.w", fmtF(1)],
          ["Group.predef.origin.v", hex8(PLANES.XY.ref * 0x10000 + 1)],
        ] });
      // center point: DATUM_POINT -> its point entity lives at entity(0)
      const rP = nextReq++;
      requests.push({ h: rP, type: REQ.DATUM_POINT, group: hg, workplane: hWp });
      params.push([rP * 0x10000 + 16, c[0]], [rP * 0x10000 + 17, c[1]]);
      const originEntity = rP * 0x10000;
      let entityB;
      if (isZAxis) {
        // helper workplane's normal points along +Z (workplane quaternion)
        entityB = 0x80000000 | (hg << 16) | 1;
      } else {
        // LINE_SEGMENT main entity at entity(0); VectorGetNum = p0 - p1,
        // so pick p0 = center, p1 = center - axis  =>  p0 - p1 = axis
        const rL = nextReq++;
        requests.push({ h: rL, type: REQ.LINE_SEGMENT, group: hg, workplane: hWp });
        params.push([rL * 0x10000 + 16, c[0]], [rL * 0x10000 + 17, c[1]]);
        params.push([rL * 0x10000 + 19, c[0] - axis[0]], [rL * 0x10000 + 20, c[1] - axis[1]]);
        entityB = rL * 0x10000;
      }
      rotateFrame = { originEntity, entityB, c, axis };
    }

    const g = nextGroup++;
    switch (op.type) {
      case "extrude": {
        const v = vec3(op.vector ?? [0, 0, 10], "extrude.vector").map((x) => x / 2);
        groups.push({ h: g, type: GRP.EXTRUDE, order: g - 1, name: op.name || `extrude-${g}`,
          fields: [...fields, ["Group.subtype", 7000], ["Group.predef.entityB.v", hex8(0x80000000 | (srcGroup << 16))]] });
        extraParams = [[groupParamHandle(g, 0), v[0]], [groupParamHandle(g, 1), v[1]], [groupParamHandle(g, 2), v[2]]];
        break;
      }
      case "translate": {
        const v = vec3(op.vector, "translate.vector").map((x) => x / 2);
        const copies = op.copies ?? 1;
        if (!(copies >= 1)) throw new Error("translate: copies must be >= 1");
        groups.push({ h: g, type: GRP.TRANSLATE, order: g - 1, name: op.name || `translate-${g}`,
          // SolveSpace step-and-repeat: valA entries include a no-op copy at
          // offset 0, so real additional copies = valA - 1.
          fields: [...fields, ["Group.subtype", 7000], ["Group.valA", fmtF(copies + 1)]] });
        extraParams = [[groupParamHandle(g, 0), v[0]], [groupParamHandle(g, 1), v[1]], [groupParamHandle(g, 2), v[2]]];
        break;
      }
      case "rotate": {
        const { originEntity, entityB, c, axis } = rotateFrame;
        // SolveSpace quaternion quirk (util.cpp RotationU + groupmesh.cpp
        // GenerateForStepAndRepeat): q = From(cos t, sin t·axis) rotates by
        // 2t, and ONE_SIDED uses ap = 2a, so copy a rotates by 4a·param3.
        // Store angle/4 so consecutive copies differ by exactly angleDeg.
        const ang = ((resolve(op.angleDeg) * Math.PI) / 180) / 4;
        const copies = op.copies ?? 1;
        if (!(copies >= 1)) throw new Error("rotate: copies must be >= 1");
        groups.push({ h: g, type: GRP.ROTATE, order: g - 1, name: op.name || `rotate-${g}`,
          fields: [...fields, ["Group.subtype", 7000], ["Group.valA", fmtF(copies + 1)],
            ["Group.predef.origin.v", hex8(originEntity)],
            ["Group.predef.entityB.v", hex8(entityB)]] });
        extraParams = [
          [groupParamHandle(g, 0), c[0]], [groupParamHandle(g, 1), c[1]], [groupParamHandle(g, 2), c[2]],
          [groupParamHandle(g, 3), ang],
          [groupParamHandle(g, 4), axis[0]], [groupParamHandle(g, 5), axis[1]], [groupParamHandle(g, 6), axis[2]],
        ];
        break;
      }
      case "lathe": {
        // LATHE (sketch.h 5101): full 360° revolution about an axis through
        // op.center along op.axis. Only predef.origin/entityB matter
        // (group.cpp GenerateShellAndMesh LATHE branch); no group params.
        const { originEntity, entityB } = rotateFrame;
        groups.push({ h: g, type: GRP.LATHE, order: g - 1, name: op.name || `lathe-${g}`,
          fields: [...fields, ["Group.subtype", 7000],
            ["Group.predef.origin.v", hex8(originEntity)],
            ["Group.predef.entityB.v", hex8(entityB)]] });
        break;
      }
      case "revolve": {
        // REVOLVE (sketch.h 5102): partial revolution. GUI sets valA=2,
        // subtype ONE_SIDED. Mesh path: sweep from 0 to 4·param3 radians
        // (groupmesh.cpp: anglef = param3 * 4); full 360° when that reaches
        // 2π. Store angleDeg/4, same quaternion convention as rotate.
        const { originEntity, entityB, c, axis } = rotateFrame;
        const ang = ((resolve(op.angleDeg ?? 360) * Math.PI) / 180) / 4;
        groups.push({ h: g, type: GRP.REVOLVE, order: g - 1, name: op.name || `revolve-${g}`,
          fields: [...fields, ["Group.subtype", 7000], ["Group.valA", fmtF(2)],
            ["Group.predef.origin.v", hex8(originEntity)],
            ["Group.predef.entityB.v", hex8(entityB)]] });
        extraParams = [
          [groupParamHandle(g, 0), c[0]], [groupParamHandle(g, 1), c[1]], [groupParamHandle(g, 2), c[2]],
          [groupParamHandle(g, 3), ang],
          [groupParamHandle(g, 4), axis[0]], [groupParamHandle(g, 5), axis[1]], [groupParamHandle(g, 6), axis[2]],
        ];
        break;
      }
      case "helix": {
        // HELIX (sketch.h 5103): like revolve plus axial translation.
        // Sweep 0..4·param3 rad; total rise = 2·param7 (groupmesh.cpp:
        // distf = param7 * 2). Store distance/2. Optional pitch (Group.valB)
        // couples them via param7·π = param3·valB (group.cpp equations):
        // when set, param7 is solved from the equation, so distance is
        // ignored; the two are mutually exclusive.
        const { originEntity, entityB, c, axis } = rotateFrame;
        if (op.pitch != null && op.distance != null) {
          throw new Error("helix: set pitch or distance, not both");
        }
        const ang = ((resolve(op.angleDeg ?? 360) * Math.PI) / 180) / 4;
        const pitch = op.pitch != null ? resolve(op.pitch) : 0;
        const dist = op.distance != null ? resolve(op.distance) / 2 : 0;
        groups.push({ h: g, type: GRP.HELIX, order: g - 1, name: op.name || `helix-${g}`,
          fields: [...fields, ["Group.subtype", 7000], ["Group.valA", fmtF(2)],
            ["Group.valB", fmtF(pitch)],
            ["Group.predef.origin.v", hex8(originEntity)],
            ["Group.predef.entityB.v", hex8(entityB)]] });
        extraParams = [
          [groupParamHandle(g, 0), c[0]], [groupParamHandle(g, 1), c[1]], [groupParamHandle(g, 2), c[2]],
          [groupParamHandle(g, 3), ang],
          [groupParamHandle(g, 4), axis[0]], [groupParamHandle(g, 5), axis[1]], [groupParamHandle(g, 6), axis[2]],
          [groupParamHandle(g, 7), dist],
        ];
        break;
      }
      default:
        throw new Error(`unknown operation type "${op.type}"`);
    }
    params.push(...extraParams);
    opGroupOf.set(op.name || `${op.type}-${g}`, g);
    opGroupOf.set(`#${g}`, g);
  }

  // ---- emit groups ----
  for (const g of groups) {
    w.field("Group.h.v", hex8(g.h));
    w.field("Group.type", g.type);
    if (g.order > 0) w.field("Group.order", g.order);
    w.field("Group.name", g.name);
    const customKeys = new Set(g.fields.map(([k]) => k));
    for (const [k, v] of g.fields) w.field(k, v);
    w.field("Group.color", "ff000000");
    if (!customKeys.has("Group.skipFirst")) w.field("Group.skipFirst", 0);
    w.field("Group.predef.swapUV", 0);
    w.field("Group.predef.negateU", 0);
    w.field("Group.predef.negateV", 0);
    w.field("Group.visible", 1);
    w.field("Group.suppress", 0);
    w.field("Group.relaxConstraints", 0);
    w.field("Group.allowRedundant", 0);
    w.field("Group.allDimsReference", 0);
    w.field("Group.scale", fmtF(1));
    w.field("Group.remap", "{\n}");
    w.add("AddGroup");
  }

  // ---- emit params (omit val line when 0, like the GUI) ----
  for (const [h, val] of params) {
    w.field("Param.h.v.", hex8(h));
    if (val !== 0) w.field("Param.val", fmtF(val));
    w.add("AddParam");
  }

  // constraint params (valP for on_line etc.)
  for (const c of constraints) {
    if (c.needValP) {
      w.field("Param.h.v.", hex8(c.h * 0x10000 + 0));
      w.add("AddParam");
    }
  }

  // ---- emit requests ----
  for (const r of requests) {
    w.field("Request.h.v", hex8(r.h));
    w.field("Request.type", r.type);
    if (r.workplane !== undefined) w.field("Request.workplane.v", hex8(r.workplane));
    w.field("Request.group.v", hex8(r.group));
    if (r.construction) w.field("Request.construction", 1);
    w.add("AddRequest");
  }

  // ---- emit constraints ----
  for (const c of constraints) {
    w.field("Constraint.h.v", hex8(c.h));
    w.field("Constraint.type", c.type);
    w.field("Constraint.group.v", hex8(c.group));
    w.field("Constraint.workplane.v", hex8(c.workplane));
    if (c.valA !== undefined && c.valA !== 0) w.field("Constraint.valA", fmtF(c.valA));
    if (c.needValP) w.field("Constraint.valP.v", hex8(c.h * 0x10000 + 0));
    if (c.ptA !== undefined) w.field("Constraint.ptA.v", hex8(c.ptA));
    if (c.ptB !== undefined) w.field("Constraint.ptB.v", hex8(c.ptB));
    if (c.entityA !== undefined) w.field("Constraint.entityA.v", hex8(c.entityA));
    if (c.entityB !== undefined) w.field("Constraint.entityB.v", hex8(c.entityB));
    w.add("AddConstraint");
  }

  return w.build();
}

module.exports = { buildSlvs, PLANES, evalExpr };
